// slide-01.js — Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'AI Model Landscape April 2026: Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative geometric blocks on right side
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 0.4, w: 2.8, h: 2.0,
    fill: { color: theme.secondary }, transparency: 40
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.6, y: 2.6, w: 2.0, h: 1.6,
    fill: { color: theme.accent }, transparency: 30
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.4, y: 4.4, w: 3.2, h: 0.9,
    fill: { color: theme.light }, transparency: 50
  });

  // Title
  slide.addText("AI Model Landscape\nApril 2026", {
    x: 0.6, y: 1.0, w: 6.0, h: 2.2,
    fontSize: 44, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    margin: 0
  });

  // Subtitle
  slide.addText("Benchmarking Intelligence, Speed, and Cost\nAcross 11 Frontier Models", {
    x: 0.6, y: 3.2, w: 6.0, h: 1.0,
    fontSize: 18, fontFace: "Calibri",
    color: theme.light, align: "left",
    margin: 0
  });

  // Source / meta
  slide.addText("Source: Artificial Analysis  |  Data captured April 10, 2026", {
    x: 0.6, y: 4.6, w: 5.0, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.light, align: "left",
    margin: 0, transparency: 30
  });

  // Accent line under title
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.0, w: 1.8, h: 0.06,
    fill: { color: theme.accent }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

