      "Muse Spark",
      "Claude Opus 4.6 (max)",
      "GPT-5.4 (xhigh)",
      "Gemini 3.1 Pro Preview"
    ],
    values: [33, 36, 42, 46, 49, 51, 52, 52, 53, 57, 57]
  }];

