    dataLabelFontSize: 10,
    dataLabelFontFace: "Calibri",
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 65
  });

  // Key takeaways panel on the right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 1.0, w: 2.9, h: 4.2,
    fill: { color: "FFFFFF" },
    rectRadius: 0.05,
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
  });

  // Panel title
  slide.addText("Key Insights", {
