// slide-05.js — Trade-offs (Mixed Media: scatter plot image + comparison table)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'No Model Wins on All Three Axes: Navigating the Intelligence-Efficiency-Cost Frontier'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.2, w: 9.2, h: 0.6,
    fontSize: 18, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Scatter plot image (left side)
  slide.addImage({
    path: "./imgs/chart_intelligence_vs_output_tokens.jpg",
    x: 0.3, y: 0.9, w: 5.0, h: 3.4,
    sizing: { type: "contain", w: 5.0, h: 3.4 }
  });

  // Caption under image
  slide.addText("Intelligence Index vs. Output Tokens Consumed During Evaluation", {
    x: 0.3, y: 4.35, w: 5.0, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, align: "center",
    margin: 0
  });

  // Right side — Proprietary vs Open-Weight summary table
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.5, y: 0.9, w: 4.2, h: 3.4,
    fill: { color: "FFFFFF" },
    rectRadius: 0.05,
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
  });

  slide.addText("Proprietary vs. Open-Weight Leaders", {
    x: 5.7, y: 0.95, w: 3.8, h: 0.4,
    fontSize: 14, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0
  });

  // Comparison table
  const headerOpts = { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle" };
  const cellPropOpts = { fill: { color: "F0F7FF" }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle" };
  const cellOpenOpts = { fill: { color: "F0FFF4" }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle" };
  const labelOpts = { fill: { color: "F5F5F5" }, color: theme.secondary, bold: true, fontSize: 10, fontFace: "Calibri", align: "left", valign: "middle" };

  const tableData = [
    [
      { text: "Metric", options: headerOpts },
      { text: "Proprietary Leader", options: headerOpts },
      { text: "Score", options: headerOpts },
      { text: "Open-Weight Leader", options: headerOpts },
      { text: "Score", options: headerOpts }
    ],
    [
      { text: "Intelligence", options: labelOpts },
      { text: "Gemini 3.1\nPro Preview", options: cellPropOpts },
      { text: "57", options: cellPropOpts },
      { text: "GLM-5.1", options: cellOpenOpts },
      { text: "51", options: cellOpenOpts }
    ],
    [
      { text: "Speed (tokens/s)", options: labelOpts },
      { text: "Gemini 3 Flash", options: cellPropOpts },
      { text: "153", options: cellPropOpts },
      { text: "gpt-oss-120B\n(high)", options: cellOpenOpts },
      { text: "218", options: cellOpenOpts }
    ],
    [
      { text: "Price ($/1M tok)", options: labelOpts },
      { text: "Gemini 3 Flash", options: cellPropOpts },
      { text: "$1.10", options: cellPropOpts },
      { text: "gpt-oss-120B\n(high)", options: cellOpenOpts },
      { text: "$0.30", options: cellOpenOpts }
    ]
  ];

  slide.addTable(tableData, {
    x: 5.6, y: 1.45, w: 4.0,
    colW: [0.85, 0.95, 0.5, 0.95, 0.5],
    border: { pt: 0.5, color: "D0D0D0" },
    rowH: [0.3, 0.5, 0.5, 0.5]
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.3, y: 4.75, w: 9.4, h: 0.6,
    fill: { color: theme.primary },
    rectRadius: 0.05
  });

  slide.addText("Every model requires explicit trade-offs among intelligence, speed, and cost. Choose based on your workload priorities.", {
    x: 0.5, y: 4.8, w: 9.0, h: 0.5,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", align: "center", valign: "middle",
    margin: 0
  });

  // Source line
  slide.addText("Source: Artificial Analysis, April 2026  |  Scatter plot measures output tokens consumed during evaluation, not throughput in tokens/s", {
    x: 0.4, y: 5.35, w: 8.0, h: 0.2,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary, align: "left",
    margin: 0
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

