// slide-06.js — Takeaways / Summary (Closing Page)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 6,
  title: 'Open Weights Close the Gap: GLM-5.1 Reaches 51 Intelligence at $2.10/M Tokens'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9.0, h: 0.7,
    fontSize: 20, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Accent line under title
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.05, w: 1.5, h: 0.05,
    fill: { color: theme.accent }
  });

  // Three key finding cards — row across the top
  const cardWidth = 2.85;
  const cardGap = 0.2;
  const cardStartX = 0.5;
  const cardY = 1.3;
  const cardH = 1.3;

  // Card 1 — Intelligence Tie
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardStartX, y: cardY, w: cardWidth, h: cardH,
    fill: { color: theme.secondary }, transparency: 30,
    rectRadius: 0.05
  });
  slide.addText("57", {
    x: cardStartX + 0.15, y: cardY + 0.1, w: 1.0, h: 0.55,
    fontSize: 32, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left",
    margin: 0
  });
  slide.addText("Co-leaders on Intelligence Index\nGemini 3.1 Pro & GPT-5.4", {
    x: cardStartX + 0.15, y: cardY + 0.65, w: 2.55, h: 0.55,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", align: "left",
    margin: 0
  });

  // Card 2 — 33x Price Gap
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardStartX + cardWidth + cardGap, y: cardY, w: cardWidth, h: cardH,
    fill: { color: theme.secondary }, transparency: 30,
    rectRadius: 0.05
  });
  slide.addText("33x", {
    x: cardStartX + cardWidth + cardGap + 0.15, y: cardY + 0.1, w: 1.0, h: 0.55,
    fontSize: 32, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left",
    margin: 0
  });
  slide.addText("Pricing gap from $0.30\nto $10.00 per 1M tokens", {
    x: cardStartX + cardWidth + cardGap + 0.15, y: cardY + 0.65, w: 2.55, h: 0.55,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", align: "left",
    margin: 0
  });

  // Card 3 — Open-Weight Gap Closing
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardStartX + 2 * (cardWidth + cardGap), y: cardY, w: cardWidth, h: cardH,
    fill: { color: theme.secondary }, transparency: 30,
    rectRadius: 0.05
  });
  slide.addText("10%", {
    x: cardStartX + 2 * (cardWidth + cardGap) + 0.15, y: cardY + 0.1, w: 1.0, h: 0.55,
    fontSize: 32, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left",
    margin: 0
  });
  slide.addText("GLM-5.1 within 10% of leaders\nat just $2.10/1M tokens", {
    x: cardStartX + 2 * (cardWidth + cardGap) + 0.15, y: cardY + 0.65, w: 2.55, h: 0.55,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", align: "left",
    margin: 0
  });

  // Actionable Recommendations section
  slide.addText("Actionable Recommendations for Model Selection", {
    x: 0.5, y: 2.85, w: 9.0, h: 0.4,
    fontSize: 16, fontFace: "Georgia",
    color: theme.light, bold: true, align: "left",
    margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.25, w: 0.8, h: 0.04,
    fill: { color: theme.accent }
  });

  // Recommendation rows — left column
  slide.addText([
    { text: "Maximize intelligence", options: { bold: true, fontSize: 13, fontFace: "Calibri", color: theme.accent, breakLine: true } },
    { text: "Gemini 3.1 Pro Preview or GPT-5.4 (score 57). Accept higher cost and moderate speed.", options: { fontSize: 11, fontFace: "Calibri", color: "FFFFFF", breakLine: true, breakLine: true } }
  ], {
    x: 0.5, y: 3.45, w: 4.2, h: 1.0,
    valign: "top", align: "left",
    margin: 0
  });

  slide.addText([
    { text: "Optimize for latency", options: { bold: true, fontSize: 13, fontFace: "Calibri", color: theme.accent, breakLine: true } },
    { text: "gpt-oss-120B (218 tokens/s) or Grok 4.20 (188 tokens/s). Trade off raw intelligence.", options: { fontSize: 11, fontFace: "Calibri", color: "FFFFFF", breakLine: true, breakLine: true } }
